'use strict';
const $=id=>document.getElementById(id), A=Arithmetic;
const names={integer:'整数运算',decimal:'小数运算',fraction:'分数运算',mixed:'混合挑战'}, levels={easy:'基础',normal:'标准',hard:'进阶'}, symbols={'+':'+','-':'−','*':'×','/':'÷'};
const config={topic:'integer',level:'normal',duration:120,operations:['+','-','*','/']};
let session=null, ticker=null, advance=null, keypadVisible=true;
let records={};try{records=JSON.parse(localStorage.getItem('mental-sprint-records')||'{}')||{}}catch(e){}
function key(){return [config.topic,config.level,config.duration,[...config.operations].sort().join('')].join(':')}
function show(id){['setup','practice','results'].forEach(view=>$(view).classList.toggle('hidden',view!==id));document.body.classList.toggle('practicing',id==='practice');window.scrollTo({top:0,behavior:'instant'})}
function hints(){
  const notes={integer:{easy:'整数从 2 起 · 加减 20 以内 · 乘除 9 以内',normal:'整数从 2 起 · 加减 100 以内 · 乘除 12 以内',hard:'整数从 2 起 · 加减 1000 以内 · 乘除 25 以内'},decimal:{easy:'一位小数加减 · 小数乘整数 · 有限小数除法',normal:'一位小数加减乘除 · 除法答案最多一位小数',hard:'两位小数加减 · 小数乘法 · 除法答案最多两位小数'},fraction:{easy:'分母 2–6 · 同分母加减 · 分数乘除',normal:'分母 2–12 · 异分母加减 · 分数乘除',hard:'分母 2–20 · 异分母加减 · 分数乘除'},mixed:{easy:'随机穿插基础整数、小数和分数题',normal:'随机穿插标准整数、小数和分数题',hard:'随机穿插进阶整数、小数和分数题'}};
  $('range-note').textContent=notes[config.topic][config.level];
  $('best-setup').textContent=records[key()]?'相同设置最佳：'+records[key()]+' 题':'每次进步一点点';
}
document.querySelectorAll('[data-topic]').forEach(button=>button.addEventListener('click',()=>{config.topic=button.dataset.topic;document.querySelectorAll('[data-topic]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button)});hints()}));
document.querySelectorAll('[data-op]').forEach(button=>button.addEventListener('click',()=>{const op=button.dataset.op,index=config.operations.indexOf(op);if(index>=0){if(config.operations.length===1)return;config.operations.splice(index,1)}else config.operations.push(op);button.classList.toggle('active',config.operations.includes(op));button.setAttribute('aria-pressed',config.operations.includes(op));hints()}));
for(const [selector,field] of [['level','level'],['duration','duration']])document.querySelectorAll('[data-'+selector+']').forEach(button=>button.addEventListener('click',()=>{config[field]=field==='duration'?Number(button.dataset[selector]):button.dataset[selector];document.querySelectorAll('[data-'+selector+']').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button)});hints()}));
function valueHtml(r,kind){return kind==='fraction'&&r.d!==1?'<span class="fraction"><span>'+r.n+'</span><span>'+r.d+'</span></span>':String(kind==='fraction'?r.n:A.decimalString(r))}
function expressionHtml(q){return '<span>'+valueHtml(q.a,q.kind)+'</span><span class="operator">'+symbols[q.op]+'</span><span>'+valueHtml(q.b,q.kind)+'</span><span class="operator">=</span><span class="operator">?</span>'}
function nextQuestion(){
  if(!session||session.ended)return;let q,attempt=0;
  do{q=A.make(config.topic,config.level,config.operations[Math.floor(Math.random()*config.operations.length)]);attempt++}while(attempt<10&&session.current&&JSON.stringify(q)===JSON.stringify(session.current));
  session.current=q;session.locked=false;session.questionStart=performance.now();$('practice').classList.remove('success-flash');$('expression').innerHTML=expressionHtml(q);$('expression').setAttribute('aria-label',A.decimalString(q.a)+' '+symbols[q.op]+' '+A.decimalString(q.b)+' 等于多少');$('question-no').textContent='QUESTION '+String(session.score+session.skipped.length+1).padStart(2,'0');$('answer').value='';$('answer').disabled=false;setHint();$('answer').focus({preventScroll:true});
}
function setHint(message,error=false){$('answer-hint').textContent=message||(session.current.kind==='fraction'?'分数输入如 1/2，也接受等值分数或精确小数':'答对自动下一题，无需按回车');$('answer-hint').classList.toggle('error',error)}
function renderTime(){if(!session||session.ended)return;const remain=Math.max(0,session.end-Date.now());const sec=Math.ceil(remain/1000);$('timer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');$('time-progress').style.width=(remain/(config.duration*1000)*100)+'%';document.querySelector('.session-bar').classList.toggle('urgent',sec<=10);if(remain<=0)endSession(true)}
function start(){clearInterval(ticker);clearTimeout(advance);session={start:Date.now(),end:Date.now()+config.duration*1000,score:0,skipped:[],solveTimes:[],ended:false,locked:false,current:null};$('practice-topic').textContent=names[config.topic]+' / '+levels[config.level]+' / '+config.duration/60+' 分钟';$('score').innerHTML='0<span>题</span>';$('pace').textContent='慢慢来，先算准。';show('practice');nextQuestion();renderTime();ticker=setInterval(renderTime,100)}
function check(explicit=false){
  if(!session||session.ended||session.locked)return;if(Date.now()>=session.end){endSession(true);return}
  const parsed=A.parse($('answer').value);
  if(A.equal(parsed,session.current.answer)){
    session.locked=true;session.score++;session.solveTimes.push((performance.now()-session.questionStart)/1000);$('score').innerHTML=session.score+'<span>题</span>';$('practice').classList.add('success-flash');setHint('正确！继续保持。');$('pace').textContent=session.score<5?'很好，找到节奏了。':session.score<15?'继续，越来越顺了。':'专注当下，保持节奏。';$('answer').disabled=true;advance=setTimeout(nextQuestion,140);
  }else if(explicit&&$('answer').value){setHint(parsed?'还没算对，再试一下。':'请输入完整的小数或分数，如 1.6、1/2。',true)}else setHint();
}
$('answer').addEventListener('input',()=>check());$('answer').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();check(true)}});
$('keypad').addEventListener('pointerdown',event=>{if(event.target.closest('button'))event.preventDefault()});
$('keypad').addEventListener('click',event=>{const button=event.target.closest('[data-key]');if(!button||!session||session.ended||session.locked)return;const k=button.dataset.key,input=$('answer');if(k==='check'){check(true);return}if(k==='clear')input.value='';else if(k==='back')input.value=input.value.slice(0,-1);else if(input.value.length<24){if(k==='-'&&input.value!=='')return;if(k==='.'&&(input.value.includes('.')||input.value.includes('/')))return;if(k==='/'&&(input.value.includes('/')||input.value.includes('.')||!input.value||input.value==='-'))return;input.value+=k}input.focus({preventScroll:true});input.setSelectionRange(input.value.length,input.value.length);check()});
$('skip').addEventListener('click',()=>{if(!session||session.ended||session.locked)return;if(Date.now()>=session.end){endSession(true);return}session.skipped.push(session.current);nextQuestion()});
$('toggle-keypad').addEventListener('click',()=>{keypadVisible=!keypadVisible;$('keypad').classList.toggle('hidden',!keypadVisible);$('practice').classList.toggle('keypad-collapsed',!keypadVisible);$('toggle-keypad').textContent=keypadVisible?'收起数字键盘':'展开数字键盘';$('toggle-keypad').setAttribute('aria-pressed',keypadVisible);$('answer').inputMode=keypadVisible?'none':'decimal';$('answer').focus({preventScroll:true})});
function endSession(completed=false){
  if(!session||session.ended)return;session.ended=true;clearInterval(ticker);clearTimeout(advance);const elapsed=completed?config.duration:Math.max(.1,(Date.now()-session.start)/1000),previous=Number(records[key()])||0,isRecord=completed&&session.score>previous;
  if(isRecord){records[key()]=session.score;try{localStorage.setItem('mental-sprint-records',JSON.stringify(records))}catch(e){}}
  $('result-score').textContent=session.score;$('result-caption').textContent=names[config.topic]+' · '+levels[config.level]+' · '+(completed?config.duration/60+' 分钟挑战完成':'提前结束，练习 '+Math.round(elapsed)+' 秒');$('result-rate').innerHTML=(session.score*60/elapsed).toFixed(1)+'<span>题</span>';$('result-average').innerHTML=session.score?(session.solveTimes.reduce((a,b)=>a+b,0)/session.score).toFixed(1)+'<span>秒</span>':'—';$('result-skips').innerHTML=session.skipped.length+'<span>题</span>';$('best-badge').classList.toggle('hidden',!isRecord);$('result-best').textContent=completed?(records[key()]?'相同主题、难度、运算和时长的最佳纪录：'+records[key()]+' 题':'完成了第一轮，下次再进步一点点。'):'提前结束的练习不计入最佳纪录。';$('review').classList.toggle('hidden',!session.skipped.length);$('review').open=false;$('review-count').textContent=session.skipped.length+' 题';$('review-list').innerHTML=session.skipped.map(q=>'<div class="review-item"><span>'+valueHtml(q.a,q.kind)+' '+symbols[q.op]+' '+valueHtml(q.b,q.kind)+'</span><span class="review-answer">= '+valueHtml(q.answer,q.kind)+'</span></div>').join('');show('results');hints();
}
$('start').addEventListener('click',start);$('again').addEventListener('click',start);$('finish').addEventListener('click',()=>endSession());$('change').addEventListener('click',()=>show('setup'));document.addEventListener('visibilitychange',()=>{if(!document.hidden)renderTime()});
$('help-button').addEventListener('click',()=>$('help').showModal());$('close-help').addEventListener('click',()=>$('help').close());$('understood').addEventListener('click',()=>$('help').close());$('help').addEventListener('click',event=>{if(event.target===$('help')){const r=$('help').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('help').close()}});
document.querySelectorAll('[data-level],[data-duration]').forEach(b=>b.setAttribute('aria-pressed',b.classList.contains('active')));hints();
